import{_ as a,Y as t,o as e,c as p,aq as r,H as n}from"./chunks/framework.DbprFcE_.js";import"./chunks/theme.BMQi1xG-.js";const u=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/home.md","filePath":"zh-cn/guide/home.md"}'),o={name:"zh-cn/guide/home.md"};function l(h,i,d,k,g,c){const s=t("NolebaseGitChangelog");return e(),p("div",null,[i[0]||(i[0]=r(`<h1 id="introduction" tabindex="-1">介绍 <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><blockquote><p><code>Gropify</code> 是一个类型安全且现代化的 Gradle 属性插件。</p></blockquote><h2 id="background" tabindex="-1">背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>这是一个为 Gradle 构建脚本设计的插件，旨在将类似 <code>gradle.properties</code> 文件中的属性以类型安全的方式引入到构建脚本中，从而避免硬编码字符串可能带来的问题。</p><p>项目图标由 <a href="https://github.com/Lagrio" target="_blank" rel="noreferrer">MaiTungTM</a> 设计，名称取自 <strong>G</strong>radleP<strong>ropify</strong>，意为针对 Gradle 属性的插件。</p><p>它是基于 <a href="https://github.com/HighCapable/SweetProperty" target="_blank" rel="noreferrer">SweetProperty</a> 重构的全新项目，借鉴了以往的设计方案，使得其在原有基础上更加完善和易用。</p><p>Gropify 的配置方案与 SweetProperty 类似，如果你正在使用 SweetProperty，你可以考虑将其迁移到 Gropify。</p><h2 id="alternatives-comparison" tabindex="-1">产品对比 <a class="header-anchor" href="#alternatives-comparison" aria-label="Permalink to &quot;产品对比&quot;">​</a></h2><p>这不是又一个普通的 <code>BuildConfig</code> 插件，以下是 Gropify 与社区现有方案的对比：</p><table tabindex="0"><thead><tr><th>功能维度</th><th>官方做法</th><th>传统插件</th><th>相关产品</th><th>Gropify</th></tr></thead><tbody><tr><td><strong>Buildscript 访问</strong></td><td>❌ 需手写硬编码字符串 <code>providers.gradleProperty(&quot;foo.bar&quot;)</code></td><td>❌ 不支持，仍需在 <code>.kts</code> 里手动读取</td><td>-</td><td><strong>✅ 自动生成链式访问器</strong> <code>gropify.foo.bar</code> (带 IDE 补全)</td></tr><tr><td><strong>源码常量生成</strong></td><td>❌ 仅 Android 支持 <code>buildConfigField</code>，KMP/JVM 不原生支持</td><td>✅ 支持生成多平台常量，但必须在 <code>.kts</code> 里显式声明字段</td><td><a href="https://github.com/gmazzo/gradle-buildconfig-plugin" target="_blank" rel="noreferrer">gmazzo/gradle-buildconfig-plugin</a></td><td><strong>✅ 零手动声明</strong>，直接根据 properties 自动推断并生成挂载</td></tr><tr><td><strong>KMP 源码多平台</strong></td><td>❌ 无法原生映射</td><td>✅ 支持通过 expect/actual 生成常量</td><td><a href="https://github.com/yshrsmz/BuildKonfig" target="_blank" rel="noreferrer">yshrsmz/BuildKonfig</a></td><td><strong>✅ 完美覆盖</strong>，自动挂载至 <code>commonMain</code> 源码集</td></tr><tr><td><strong>配置冗余度</strong></td><td><strong>❌ 高</strong> (Key 散落在各处字符串中)</td><td><strong>⚠️ 中</strong> (必须在 <code>.kts</code> 里手写映射关系)</td><td>-</td><td><strong>✅ 极低</strong> (Properties 即 Schema)</td></tr><tr><td><strong>设计哲学</strong></td><td>散装的能力碎片</td><td>CodeGen-First (代码生成工具)</td><td>-</td><td>Properties-Centric (属性中心化驱动)</td></tr></tbody></table><h2 id="features-overview" tabindex="-1">功能一览 <a class="header-anchor" href="#features-overview" aria-label="Permalink to &quot;功能一览&quot;">​</a></h2><p>Gropify 主要针对 Kotlin DSL 构建脚本设计，Groovy 语言可以直接将 <code>gradle.properties</code> 文件中的属性作为变量使用，但是你也可以通过 Gropify 来实现类型安全的属性访问。</p><p>Gropify 同时支持将类似 <code>gradle.properties</code> 文件中的属性以类型安全的方式生成到 Kotlin、Java、Android 项目的源码中以供应用程序运行时使用，功能类似 Android 的 <code>BuildConfig</code> 中的 <code>buildConfigField</code> 功能。</p><p>假设我们有以下 <code>gradle.properties</code> 文件。</p><blockquote><p>示例如下</p></blockquote><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project.app.name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Gropify-Demo</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project.app.version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1.0.0</span></span></code></pre></div><p>这是 Gropify 自动生成的代码调用示例。</p><blockquote><p>构建脚本 (Kotlin DSL、Groovy DSL)</p></blockquote><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify.project.app.name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify.project.app.version</span></span></code></pre></div><div class="language-groovy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">groovy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gropify</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span></code></pre></div><blockquote><p>源代码 (Kotlin、Java)</p></blockquote><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_NAME</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_VERSION</span></span></code></pre></div><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_NAME;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appVersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MyAppProperties.PROJECT_APP_VERSION;</span></span></code></pre></div><p>Gropify 同样支持 Kotlin Multiplatform 项目，你可以在 <code>commonMain</code> 源集中使用生成的属性类。</p><h2 id="language-requirement" tabindex="-1">语言要求 <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;语言要求&quot;">​</a></h2><p>推荐使用 Kotlin DSL 来配置项目的构建脚本，Groovy 语言同样受支持，但在纯 Groovy 项目中部分配置语法可能存在兼容性问题。</p><p>在 Groovy DSL 中使用此插件发生的任何问题，我们都将不再负责排查和修复，并且在后期版本可能会完全不再支持 Groovy DSL。</p><h2 id="contribution" tabindex="-1">功能贡献 <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;功能贡献&quot;">​</a></h2><p>本项目的维护离不开各位开发者的支持和贡献，目前这个项目处于初期阶段，可能依然存在一些问题或者缺少你需要的功能， 如果可能，欢迎提交 PR 为此项目贡献你认为需要的功能或前往 <a href="https://github.com/HighCapable/Gropify/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 向我们提出建议。</p>`,29)),n(s)])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
